previsioni.codice:
extends RefCounted

func run() -> int:
	var base_size := Vector2(1152, 648)
	var window_size := Vector2(1920, 1080)
	var scale_factor: float = minf(window_size.x / base_size.x, window_size.y / base_size.y)
	var effective_width: float = base_size.x * scale_factor
	var total_black_bars_px: float = window_size.x - effective_width
	return int(total_black_bars_px)

extends RefCounted

func run() -> float:
	var base_size := Vector2(1152, 648)
	var window_size := Vector2(1280, 1024)
	var scale_factor: float = minf(window_size.x / base_size.x, window_size.y / base_size.y)
	var effective_height: float = base_size.y * scale_factor
	var total_letterbox_y: float = window_size.y - effective_height
	return total_letterbox_y

file.contenuto:
extends Node

var current_score: int = 0
var player_name: String = ""
var difficulty: int = 2


func reset_session() -> void:
	current_score = 0


func register_score(points: int) -> void:
	current_score = points


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("toggle_fullscreen"):
		toggle_fullscreen()


func toggle_fullscreen() -> void:
	var current_mode: int = DisplayServer.window_get_mode()
	if current_mode == DisplayServer.WINDOW_MODE_FULLSCREEN:
		DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_WINDOWED)
	else:
		DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_FULLSCREEN)

blocchi.codice:
extends Node

## Autoload globale registrato come "Game".
## Mantiene lo stato persistente e gestisce le funzioni della finestra.

var current_player_name: String = ""
var high_score: int = 0


func _ready() -> void:
	# Permette a questo nodo di continuare a leggere l'input anche se il gioco va in pausa
	process_mode = Node.PROCESS_MODE_ALWAYS


func _process(_delta: float) -> void:
	if Input.is_action_just_pressed("toggle_fullscreen"):
		toggle_fullscreen()


## Alterna tra la visualizzazione a finestra e lo schermo intero.
func toggle_fullscreen() -> void:
	if DisplayServer.window_get_mode() == DisplayServer.WINDOW_MODE_WINDOWED:
		DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_FULLSCREEN)
	else:
		DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_WINDOWED)
